## 🎯 Dans cette leçon

Tout montage électronique repose sur trois grandeurs : **la tension**, **le courant** et **la résistance**. Une seule formule les relie : la **loi d'Ohm**. Quand tu la maîtrises, tu sais pourquoi une LED grille, quelle résistance choisir et quelle alimentation acheter.

À la fin de cette leçon, tu sauras :

- expliquer ce que sont la tension U, le courant I, la résistance R et la puissance P ;
- calculer l'une de ces grandeurs quand tu connais les deux autres ;
- choisir la résistance qui protège une LED ;
- vérifier tes calculs avec un multimètre.

blocs.code:
/*
  FOUNATEK ACADEMY
  Leçon 0.1 — Tension et courant électriques

  Montage :
  D9 -> Résistance 220 ohms -> Anode LED
  Cathode LED -> GND
*/

// Broche D9, comme dans le cours
const int BROCHE_LED = 9;

// Données du circuit
const float U = 5.0;          // Tension Arduino (V)
const float U_LED = 2.0;      // Tension LED rouge (V)
const float R = 220.0;        // Résistance utilisée (ohms)
const float I_CIBLE = 0.015;  // Courant cible : 15 mA

// Calculs électriques
float U_R;
float I;
float I_mA;
float R_CALCULEE;
float P_R;
float P_LED;

int cycle = 0;

void setup() {

  pinMode(BROCHE_LED, OUTPUT);

  // Initialisation du moniteur série
  Serial.begin(9600);

  delay(1000);

  Serial.println();
  Serial.println("======================================");
  Serial.println("          FOUNATEK ACADEMY");
  Serial.println("======================================");
  Serial.println("LECON 0.1 : TENSION ET COURANT");
  Serial.println("Simulation Arduino UNO + LED");
  Serial.println("--------------------------------------");

  // 1. Données du circuit
  Serial.println();
  Serial.println("1. DONNEES DU CIRCUIT");

  Serial.print("Broche Arduino : D");
  Serial.println(BROCHE_LED);

  Serial.print("Tension U : ");
  Serial.print(U, 2);
  Serial.println(" V");

  Serial.print("Tension LED : ");
  Serial.print(U_LED, 2);
  Serial.println(" V");

  Serial.print("Resistance R : ");
  Serial.print(R, 0);
  Serial.println(" ohms");

  Serial.print("Courant cible : ");
  Serial.print(I_CIBLE * 1000, 1);
  Serial.println(" mA");

  // 2. Calcul de la résistance théorique
  R_CALCULEE = (U - U_LED) / I_CIBLE;

  Serial.println();
  Serial.println("2. CHOIX DE LA RESISTANCE");

  Serial.println("R = (U - U_LED) / I_cible");

  Serial.println("R = (5 - 2) / 0.015");

  Serial.print("R calculee = ");
  Serial.print(R_CALCULEE, 0);
  Serial.println(" ohms");

  Serial.println("Valeur normalisee choisie : 220 ohms");

  // 3. Tension sur la résistance
  U_R = U - U_LED;

  Serial.println();
  Serial.println("3. TENSION SUR LA RESISTANCE");

  Serial.println("U_R = U - U_LED");
  Serial.println("U_R = 5 - 2");

  Serial.print("U_R = ");
  Serial.print(U_R, 2);
  Serial.println(" V");

  // 4. Loi d'Ohm
  I = U_R / R;
  I_mA = I * 1000.0;

  Serial.println();
  Serial.println("4. LOI D'OHM");

  Serial.println("U_R = R x I");
  Serial.println("I = U_R / R");
  Serial.println("I = 3 / 220");

  Serial.print("I = ");
  Serial.print(I, 6);
  Serial.println(" A");

  Serial.print("I = ");
  Serial.print(I_mA, 2);
  Serial.println(" mA");

  // 5. Puissance dissipée
  P_R = U_R * I;
  P_LED = U_LED * I;

  Serial.println();
  Serial.println("5. CALCUL DES PUISSANCES");

  Serial.println("P_R = U_R x I");

  Serial.print("P_R = ");
  Serial.print(P_R, 4);
  Serial.println(" W");

  Serial.print("P_R = ");
  Serial.print(P_R * 1000, 2);
  Serial.println(" mW");

  Serial.println("P_LED = U_LED x I");

  Serial.print("P_LED = ");
  Serial.print(P_LED * 1000, 2);
  Serial.println(" mW");

  Serial.println();
  Serial.println("6. VERIFICATION");

  if (P_R < 0.25) {
    Serial.println("Resistance 1/4 W : puissance OK");
  } else {
    Serial.println("ATTENTION : puissance trop elevee !");
  }

  Serial.println();
  Serial.println("======================================");
  Serial.println("       DEBUT DE LA SIMULATION");
  Serial.println("======================================");
}

void loop() {

  cycle++;

  Serial.println();
  Serial.print("========== CYCLE ");
  Serial.print(cycle);
  Serial.println(" ==========");

  // Allumage
  digitalWrite(BROCHE_LED, HIGH);

  Serial.println("ETAT : LED ALLUMEE");
  Serial.println("Broche D9 : HIGH (5 V)");

  Serial.print("Courant estime : ");
  Serial.print(I_mA, 2);
  Serial.println(" mA");

  Serial.println("Attente : 1 seconde");

  delay(1000);

  // Extinction
  digitalWrite(BROCHE_LED, LOW);

  Serial.println();
  Serial.println("ETAT : LED ETEINTE");
  Serial.println("Broche D9 : LOW (0 V)");
  Serial.println("Courant estime : 0 mA");
  Serial.println("Attente : 1 seconde");

  delay(1000);
}

