// Leçon 0.3 — la même tension lue en analogique et en numérique
void setup() {
  Serial.begin(9600);
}

void loop() {
  int n = analogRead(A0);          // 0 à 1023
  float u = n * 5.0 / 1023.0;      // conversion en volts
  int etat = digitalRead(A0);      // 0 ou 1

  Serial.print("N = ");          Serial.print(n);
  Serial.print("  U = ");        Serial.print(u, 2);
  Serial.print(" V  logique = "); Serial.println(etat);
  delay(300);
}

// Solution du mini-défi : trois zones pour le potentiomètre
void setup() {
  Serial.begin(9600);
}

void loop() {
  int n = analogRead(A0);
  if (n < 341) {              // 0 à 340 : premier tiers
    Serial.println("BAS");
  } else if (n < 682) {       // 341 à 681 : deuxième tiers
    Serial.println("MILIEU");
  } else {                    // 682 à 1023 : dernier tiers
    Serial.println("HAUT");
  }
  delay(300);
}

