// Leçon 0.4 — tester le câblage de LED1 (schéma : D13 → R1 → LED1 → GND)
const int LED1 = 13;   // D13, comme sur le schéma

void setup() {
  Serial.begin(9600);
  pinMode(LED1, OUTPUT);
}

void loop() {
  digitalWrite(LED1, HIGH);   // D13 → R1 → LED1 → GND : le courant passe
  Serial.println("D13 = HIGH : LED1 doit s'allumer");
  delay(2000);
  digitalWrite(LED1, LOW);    // plus de courant
  Serial.println("D13 = LOW : LED1 doit s'éteindre");
  delay(2000);
}

