// Leçon 0.6 — mini-voltmètre : fil sur A0 = pointe rouge, GND = COM
// Ne jamais dépasser 5 V sur A0 !
void setup() {
  Serial.begin(9600);
}

void loop() {
  long somme = 0;
  for (int k = 0; k < 20; k++) {   // moyenne de 20 lectures
    somme += analogRead(A0);
  }
  float u = somme / 20.0 * 5.0 / 1023.0;
  Serial.print("U = ");
  Serial.print(u, 2);
  Serial.println(" V");
  delay(500);
}

