## 🎯 Dans cette leçon

Un microcontrôleur ne connaît que deux états : la tension est **haute** (1) ou **basse** (0). Pour représenter des nombres, des lettres, des couleurs ou des mesures, il les écrit avec ces deux chiffres : c'est le **binaire**.

À la fin de cette leçon, tu sauras :

- lire un nombre binaire grâce aux poids des bits ;
- convertir un nombre décimal en binaire, et l'inverse ;
- calculer combien de valeurs tiennent sur n bits ;
- lire l'hexadécimal (0x27, 0xFF) et le code ASCII ;
- afficher un compteur binaire sur 4 LED avec `bitRead()`.

blocs.code:
// Leçon 0.7 — compteur binaire de 0 à 15 sur 4 LED
const int LEDS[4] = {2, 3, 4, 5};   // poids 1, 2, 4, 8

void setup() {
  for (int k = 0; k < 4; k++) pinMode(LEDS[k], OUTPUT);
  Serial.begin(9600);
}

void loop() {
  for (int n = 0; n < 16; n++) {          // 4 bits : 16 valeurs, de 0 à 15
    for (int k = 0; k < 4; k++) {
      digitalWrite(LEDS[k], bitRead(n, k)); // bit de rang k de n : 0 ou 1
    }
    Serial.print(n);
    Serial.print(" = ");
    Serial.println(n, BIN);               // affiche n en binaire
    delay(1000);
  }
}

// Solution du mini-défi : +1 à chaque appui sur le bouton D7
const int LEDS[4] = {2, 3, 4, 5};
const int BOUTON = 7;
int n = 0;
bool avant = HIGH;                       // état précédent du bouton

void setup() {
  for (int k = 0; k < 4; k++) pinMode(LEDS[k], OUTPUT);
  pinMode(BOUTON, INPUT_PULLUP);         // relâché = HIGH, appuyé = LOW
}

void loop() {
  bool maintenant = digitalRead(BOUTON);
  if (avant == HIGH && maintenant == LOW) {   // on vient d'appuyer
    n = (n + 1) % 16;                         // après 15, retour à 0
    delay(30);                                // anti-rebond simple
  }
  avant = maintenant;
  for (int k = 0; k < 4; k++) digitalWrite(LEDS[k], bitRead(n, k));
}

