// Leçon 0.8 — une porte ET avec deux boutons (et les autres portes)
const int BP1 = 2, BP2 = 3, LED = 8;

void setup() {
  pinMode(BP1, INPUT_PULLUP);   // relâché = HIGH, appuyé = LOW
  pinMode(BP2, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool a = (digitalRead(BP1) == LOW);   // a = 1 si BP1 est appuyé
  bool b = (digitalRead(BP2) == LOW);   // b = 1 si BP2 est appuyé
  bool s = a && b;                      // ET ; essaie aussi a || b, !a, a != b
  digitalWrite(LED, s);

  Serial.print("A = "); Serial.print(a);
  Serial.print("  B = "); Serial.print(b);
  Serial.print("  S = "); Serial.println(s);
  delay(100);
}
